from pocket_coffea.cuts.hlt_triggers import hlt_trigger_sel
from pocket_coffea.cuts.object_selection import (
    object_multiplicity,
    btag_multiplicity,
)

# Configuration parameters
config = {
    "year": 2018,
    "channel": "semileptonic",
    "primary_dataset": "semileptonic",
}

