skim_cuts = {
    "triggers": hlt_trigger_sel(dataset=config["primary_dataset"]),
}

# Preselection cuts - kinematic and tagging requirements
preselection_cuts = {
    "jet_multiplicity": object_multiplicity(
        collection="JetGood",
        min_count=4,
        pt_min=30.0,
    ),
    "btag_multiplicity": btag_multiplicity(
        collection="JetGood",
        min_count=2,
    ),
}

# Combine into complete cut configuration
cuts = {
